source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                points.setdefault(value, []).append((r, c))

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    twos = points.get(2, [])
    verticals = points.get(3, []) + points.get(6, [])
    for r, c in points.get(1, []):
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)
    for r, c in twos:
        for dc in (1, 2, 3):
            put(r, c - dc, 5)
        put(r, c - 4, 2)
    for r, c in points.get(3, []):
        for dr in (1, 2):
            put(r + dr, c, 5)
        put(r + 3, c, 3)
    for r, c in points.get(6, []):
        for dr in (1, 2, 3, 4, 5):
            put(r - dr, c, 5)
        put(r - 6, c, 6)

    # A crossing between a 2's leftward stroke and a 3/6 vertical stroke
    # sends a diagonal 4 ray down-left.
    for r2, c2 in twos:
        for rv, cv in verticals:
            if c2 - 4 <= cv <= c2:
                if (rv <= r2 <= rv + 3) if (rv, cv) in points.get(3, []) else (rv - 6 <= r2 <= rv):
                    rr, cc = r2, cv
                    while rr < h and cc >= 0:
                        put(rr, cc, 4)
                        rr += 1
                        cc -= 1
    return out
'''
